<script>
// 引入 start
const QRCode = require('qrcode')
import '@photo-sphere-viewer/core/index.css'
import '@photo-sphere-viewer/markers-plugin/index.css'
import { MarkersPlugin } from '@photo-sphere-viewer/markers-plugin'
import { events } from '@photo-sphere-viewer/core'
import {
  // eslint-disable-next-line no-unused-vars
  getProductCatalogs,
  getProductRecommendTags,
  updateProduct,
  sortScene,
  updateScene,
  removeHotpot,
  getTourNodes,
  tourNodesSet,
  deleteTourNode,
  saveMapSceneMarkers,
  getPlaneGraph,
} from '@/api/vr'
// eslint-disable-next-line no-unused-vars
import { getRouteUrl, convertCoordinatesToYawPitch } from '@/utils/tools'
import FootBody from '@/components/home/FootBody'
import { renderVRMixin } from '@/mixins/renderVR'
import AnimateIcon from '@/utils/animateIcon'
// 引入 end

// 默认值 start
const defaultModel = {
  id: undefined,
  title: '',
  anonymousShow: 1,
  type: 'pictures',
  address: '',
  remark: '',
  cover: '',
  coverFull: '',
  pcTipImg: '',
  mobileTipImg: '',
  password: '',
  recommendTagIds: [],
  customTags: '',
  hotPoints: [],
}

// 默认值 end

export default {
  name: 'DIY',
  mixins: [renderVRMixin],
  components: {
    FootBody,
    VrHeader: () => import('../layout/header.vue'),
    VrUpload: () => import('@/components/VrUpload.vue'),
    SettingLogoForm: () => import('./form/logoSet.vue'),
    SettingBeginForm: () => import('./form/beginSet.vue'),
    SettingAdForm: () => import('./form/adSet.vue'),
    SettingWatermarkForm: () => import('./form/watermarkSet.vue'),
    SettingShareForm: () => import('./form/shareSet.vue'),
    viewSetting: () => import('./form/view.vue'),
    hotpotSetting: () => import('./form/hotpoint.vue'),
    LoopViewSetting: () => import('./form/LoopView.vue'),
    MapSetting: () => import('./form/Map.vue'),
    PointMarkerTool: () => import('@/components/point-marker-tool'),
    MapPointConfig: () => import('./form/MapPointConfig.vue'),
  },
  data() {
    return {
      currentToolbarCode: 'basic', // 当前操作栏
      toolbarItems: [
        // 左侧操作栏
        {
          code: 'basic',
          title: '基础',
          icon: 'el-icon-setting',
        },
        {
          code: 'view',
          title: '视图',
          icon: 'el-icon-view',
        },
        {
          code: 'hotpot',
          title: '热点',
          icon: 'el-icon-map-location',
        },
        {
          code: 'loop_view',
          title: '导游',
          icon: 'el-icon-s-promotion',
        },
        {
          code: 'map',
          title: '地图',
          icon: 'el-icon-map-location',
        },
      ],
      saveLoading: false, // 保存loading
      publishLoading: false, // 发布loading
      model: Object.assign({}, defaultModel), // 表单
      rules: {
        title: [
          { required: true, message: '请输入作品名称', trigger: 'blur' },
          {
            min: 2,
            max: 100,
            message: '长度在 3 到 100 个字符',
            trigger: 'blur',
          },
        ],
        cover: [{ required: true, message: '请上传封面', trigger: 'blur' }],
      },
      catalogItems: [], // 作品分类列表
      tagItems: [], // 作品分类推荐标签
      customTagInputVisible: false, // 自定义tag输入框是否显示
      customTagInputValue: '', // 自定义tag输入框值
      customTags: [], // 定义tag
      viewForm: {
        // 访问设置
        encrypt: 0,
        password: '',
      },
      vrCurrentCenterAngleImgCanvas: null,
      vrCurrentCenterAngleImgDataURL: null, // 当前中心角度图片
      hotDrawer: false, // 打开热点配置抽屉开关
      tourSwitchValue: false, // 导游开关
      tourMarkers: [], // 导游值
      electronicMapBaseMapUrl: null, // 电子地图底图
      addMapNodeTrue: false, // 是否点击添加场景标记点位
      addMapNodeSceneId: null, // 当前点击添加场景标记点位场景id
      selectCircleDgeCanvasWidth: undefined, // 角度选择器-宽度
      selectCircleDgeCanvasHeight: undefined, // 角度选择器-高度
      mapSceneNodes: [], // 电子地图场景节点
      activeMapSceneNode: null, // 电子地图场景节点当前节点
      mapBaseMapScale: 1, // 电子地图放大比例值
      mapCenterPoint: {
        position: { x: 0, y: 0 },
        scale: { scaleW: 1, scaleY: 1 },
      },
      planeGraph: null, // 电子地图配置
      polygonDraw: {
        drawing: false,
        scale: 0.005,
        polygons: [],
        points: [],
        markers: [],
        polygonMarkers: [],
        rectangle: false,
      },
    }
  },
  watch: {
    vrOptions: {
      deep: true,
      handler() {
        this._applyVrPlayOptions()
      },
    },
  },
  computed: {
    viewURL() {
      let routeUrl = this.$router.resolve({
        path: `/vr/${this.product.code}`,
      })

      return getRouteUrl(`${routeUrl.href}`)
    },
    excludeMapSceneNodes() {
      return this.activeMapSceneNode
        ? this.mapSceneNodes.filter(
            (node) => node.sceneId !== this.activeMapSceneNode.sceneId
          )
        : this.mapSceneNodes
    },
  },
  created() {
    const id = this.$route.params.id || 0
    this.getProduct(id, this.onInitProductCall)
    this.getCatalogs()
    this.listenEvents()
  },
  methods: {
    // 获取作品详情后的回调
    onInitProductCall() {
      this.model = {
        id: this.product.id,
        title: this.product.title,
        password: this.product.password,
        anonymousShow: this.product.anonymousShow,
        type: this.product.type,
        address: this.product.address,
        remark: this.product.remark,
        cover: this.product.cover,
        catalogId: this.product.catalogId,
        coverFull: this.product.coverFull,
        pcTipImg: '',
        mobileTipImg: '',
        recommendTagIds: this.product.recommendTagIds,
        customTags: this.product.customTags.join('|'),
      }
      this.customTags = this.product.customTags
      if (this.model.catalogId) {
        this.getRecommendTags()
      }

      if (this.product.scenes.length) {
        this.currentScene = this.product.scenes[0]
      }

      this.$nextTick(() => {
        this.setSceneList(this.product.scenes)
        this.makeQrCode()
      })
    },
    // 渲染vr后执行回调
    renderVRCallback() {
      if (this.currentToolbarCode === 'view') {
        setTimeout(() => {
          this.setVRCenterAngle()
        }, 500)
      }

      this.markersPlugin = this.vrViewer.getPlugin(MarkersPlugin)
      this.vrViewer.navbar.getButton('markers') &&
        this.vrViewer.navbar.getButton('markers').destroy()
      this.vrViewer.navbar.getButton('markersList') &&
        this.vrViewer.navbar.getButton('markersList').destroy()
      this.vrViewer.addEventListener(events.ReadyEvent.type, this.vrOnReady)
      this.vrViewer.addEventListener(events.RenderEvent.type, this.vrOnRender)
      this.vrViewer.removeEventListener('click')
      this.vrViewer.addEventListener('click', this.vrOnClick)
      this.vrViewer.addEventListener('dblclick', this.vrOnDblClick)
      this.markersPlugin.addEventListener(
        'select-marker',
        this.vrMarkerOnSelectMarker
      )
    },
    // 全局事件监听
    listenEvents() {
      // eslint-disable-next-line no-unused-vars
      // 场景拖拽排序
      this.$bus.$on('onSceneSortableEnd', (to, from) => {
        // eslint-disable-next-line no-unused-vars
        sortScene(to.sid, from.sid).then((_result) => {
          this.getProductScenes().then((scenes) => {
            this.setSceneList(scenes)
          })
        })
        // await sortScene(this.id, to, from)
      })

      // 当前场景切换
      this.$bus.$on('onCurrentSceneChange', (scene) => {
        this.execSceneChange(scene.id)
      })

      this.$bus.$on('onHotDrawerStatusChange', (value) => {
        console.log('修改热点开关状态:', value)
        this.hotDrawer = value
        document.querySelector('.psv-markers-svg-container').style.cursor =
          value ? 'cell' : 'move'
      })

      // 移除场景热点
      this.$bus.$on('onRemoveHotpot', (hotModel) => {
        let ids = []
        if (hotModel.iconMarkerParams && hotModel.iconMarkerParams.id) {
          ids.push(hotModel.iconMarkerParams.id)
          try {
            this.markersPlugin.removeMarker(hotModel.iconMarkerParams.id)
          // eslint-disable-next-line no-empty
          } catch(e) {}
        }
        if (
          hotModel.iconTitleMarkerParams &&
          hotModel.iconTitleMarkerParams.id
        ) {
          ids.push(hotModel.iconTitleMarkerParams.id)
          try {
            this.markersPlugin.removeMarker(hotModel.iconTitleMarkerParams.id)
          // eslint-disable-next-line no-empty
          } catch(e) {}
        }
        this.hotpotMarkerItems = this.hotpotMarkerItems.filter(
          (item) => !ids.includes(item.id)
        )
      })

      // 热点修改
