    // 生成预览的二维码
    makeQrCode(src = null) {
      const img = new Image()
      img.src = src ? src : this.product.coverFull // 替换为你的图片路径
      const canvas = document.getElementById('canva-qrcode')
      // canvas.width = 256 // 设置 Canvas 宽度为 500 像素
      // canvas.height = 256 // 设置 Canvas 高度为 300 像素
      const ctx = canvas.getContext('2d')
      // 要编码的数据
      const dataToEncode = this.viewURL
      // 生成二维码
      QRCode.toCanvas(
        canvas,
        dataToEncode,
        {
          width: 180,
          height: 180,
        },
        function (error) {
          if (error) console.error(error)

          img.width = 35
          img.height = (img.width * canvas.height) / canvas.width
          // 在图片加载后将其绘制到二维码上
          img.onload = function () {
            const centerX = (canvas.width - img.width) / 2 // 计算居中位置
            const centerY = (canvas.height - img.height) / 2
            // 创建遮罩
            ctx.fillStyle = 'rgba(0, 0, 0, 0)' // 白色遮罩（或者使用 'rgba(0, 0, 0, 0)' 来设置透明）
            ctx.fillRect(centerX, centerY, img.width, img.height) // 在图片位置创建遮罩
            // 绘制二维码
            // QRCode.toCanvas(canvas, dataToEncode, function () {
            //   ctx.globalCompositeOperation = 'destination-out' // 使用 destination-out 模式
            //   ctx.drawImage(img, centerX, centerY, img.width, img.height) // 绘制图片
            // })
            //ctx.globalCompositeOperation = 'source-xor' // 设置绘制模式，确保图片在二维码下面
            ctx.drawImage(img, centerX, centerY, img.width, img.height) // 自定义图片在二维码上的位置和尺寸
          }
        }
      )
    },
