    // 点击绘制多边形
    onPolygonDraw(position) {
      // position: position
      const point = [position.yaw, position.pitch]
      this.polygonDraw.points.push(point)
      if (this.isPolygonComplete(this.polygonDraw.points)) {
        console.log('绘制完成一个多边形')
        this.savePolygon(this.polygonDraw.points)
        return
      }

      const marker = {
        id: `polygon_draw_point_${new Date().getTime()}`,
        square: 20,
        position: position,
        svgStyle: {
          fill: 'rgba(255, 255, 255, 1)', // White color
        },
      }

      this.markersPlugin.addMarker(marker)
      this.polygonDraw.markers.push(marker)
    },
    isPolygonComplete(points) {
      // 如果绘制的点数量小于3，不是一个有效的多边形
      // console.log('points:', points)
      if (points.length < 3) {
        return false
      }

      // 获取第一个点和最后一个点的坐标
      const firstPoint = points[0]
      const lastPoint = points[points.length - 1]
      const tolerance = 5 * this.polygonDraw.scale
      // 计算最后一个点和第一个点的距离
      const distance = Math.sqrt(
        Math.pow(firstPoint[0] - lastPoint[0], 2) +
          Math.pow(firstPoint[1] - lastPoint[1], 2)
      )

      // 如果距离小于误差范围，形成了闭合的多边形
      return distance <= tolerance
      // 如果第一个点和最后一个点的坐标相同，则形成了闭合的多边形
      // return firstPoint[0] === lastPoint[0] && firstPoint[1] === lastPoint[1]
    },
    // 开启多边形绘制开关
    onDrawToolFormSwitch(flag, rectangle = false) {
      this.polygonDraw.drawing = flag
      this.polygonDraw.rectangle = rectangle
      if (flag) {
        this.$message.warning('如果需要进行其他操作,请先结束绘制多边形')
      } else {
        this.$message.warning('关闭绘制后,将清除已绘制的多边形')
        this.polygonDraw.points = []
        this.polygonDraw.polygons = []
        this.markersPlugin.removeMarkers(this.polygonDraw.markers)
        this.markersPlugin.removeMarkers(this.polygonDraw.polygonMarkers)
        this.polygonDraw.markers = []
        this.polygonDraw.polygonMarkers = []
      }
    },
    // 删除多边形绘制的最后一个点
    onDrawToolRemoveLastPoint() {
      if (this.polygonDraw.markers.length <= 1) {
        return
      }
      const marker = this.polygonDraw.markers.pop()
      this.polygonDraw.points.pop()
      this.markersPlugin.removeMarker(marker.id)
    },
    // 在达到多边形条件后，将绘制的点合并成一个多边形并保存
    async savePolygon(points) {
      // 如果点的数量小于3，不是一个有效的多边形，直接返回
      if (points.length < 3) {
        return
      }

      // 添加第一个点到最后一个点，闭合多边形
      // points.push(points[0])
      // 检查最后一个点是否已经和第一个点相同，如果相同则不添加
      const firstPoint = points[0]
      const lastPoint = points[points.length - 1]

      const tolerance = 5 * this.polygonDraw.scale
      const distance = Math.sqrt(
        Math.pow(firstPoint[0] - lastPoint[0], 2) +
          Math.pow(firstPoint[1] - lastPoint[1], 2)
      )

      if (distance > tolerance) {
        // 如果最后一个点和第一个点不一样，才闭合多边形
        points.push(firstPoint)
      }
      // 将多边形的点位信息保存到已绘制的多边形数组中
      if (points.length === 5 && this.polygonDraw.rectangle) {
        const rePoints = points.slice(0, 4)
        const viewerCoords = rePoints.map((point) => {
          return this.vrViewer.dataHelper.sphericalCoordsToViewerCoords({
            pitch: point[1],
            yaw: point[0],
          })
        })
        const adjViewerCoords = this.adjustToRectangle(viewerCoords)
        console.log('viewerCoords:', viewerCoords)
        console.log('adjViewerCoords:', adjViewerCoords)
        const adjPoints = adjViewerCoords.map((point) => {
          const position =
            this.vrViewer.dataHelper.viewerCoordsToSphericalCoords(point)
          return [position.yaw, position.pitch]
        })
        console.log('adjPoints:', adjPoints)
        points = adjPoints
      }
      this.polygonDraw.polygons.push(points)
      // 在全景图上绘制多边形
      let polygonMarker = {
        id: `polygon_draw_${new Date().getTime()}`,
        polygon: points,
        svgStyle: {
          fill: this.$refs.hotpotSetting.drawToolForm.bgColor, // White color 'rgba(255, 255, 255, 1)'
          stroke: this.$refs.hotpotSetting.drawToolForm.lineColor,
        },
      }
      this.polygonDraw.points = []
      this.markersPlugin.removeMarkers(this.polygonDraw.markers)
      this.polygonDraw.markers = []
      const afterMarkerId = await this.$refs.hotpotSetting.addPolygonMarker(
        polygonMarker,
        this.polygonDraw.polygonMarkers.length
      )
      polygonMarker.id = afterMarkerId
      this.markersPlugin.addMarker(polygonMarker)
      this.polygonDraw.polygonMarkers.push(polygonMarker)
      this.polygonDraw.drawing = false
    },
    findCorners(points) {
      let leftTop = null
      let rightTop = null
      let leftBottom = null
      let rightBottom = null

      points.forEach((point) => {
        const { x, y } = point
        // 左上角：y 值最小，x 值最小
        if (!leftTop || y < leftTop.y || (y === leftTop.y && x < leftTop.x)) {
          leftTop = point
        }
        // 右上角：y 值最小，x 值最大
        if (
          !rightTop ||
          y < rightTop.y ||
          (y === rightTop.y && x > rightTop.x)
        ) {
          rightTop = point
        }
        // 左下角：y 值最大，x 值最小
        if (
          !leftBottom ||
          y > leftBottom.y ||
          (y === leftBottom.y && x < leftBottom.x)
        ) {
          leftBottom = point
        }
        // 右下角：y 值最大，x 值最大
        if (
          !rightBottom ||
          y > rightBottom.y ||
          (y === rightBottom.y && x > rightBottom.x)
        ) {
          rightBottom = point
        }
      })

      return [leftTop, rightTop, rightBottom, leftBottom]
    },
    adjustToRectangle(points) {
      // 初始化最小和最大值
      let minX = Infinity,
        maxX = -Infinity
      let minY = Infinity,
        maxY = -Infinity

      // 遍历点集，找出最大和最小的 x 和 y 值
      points.forEach((point) => {
        const { x, y } = point

        if (x < minX) minX = x
        if (x > maxX) maxX = x
        if (y < minY) minY = y
        if (y > maxY) maxY = y
      })

      // 生成矩形的四个角
      const rectangle = [
        { x: minX, y: minY }, // 左上角
        { x: maxX, y: minY }, // 右上角
        { x: maxX, y: maxY }, // 右下角
        { x: minX, y: maxY }, // 左下角
      ]

      return rectangle
    },
