    // 添加导游节点
    onAddTourMarker() {
      const position = this.vrViewer.getPosition()
      const exist = this.tourMarkers.findIndex(
        (item) =>
          item.sceneId === this.currentScene.id &&
          item.position.yaw === position.yaw &&
          item.position.pitch === position.pitch
      )
      if (exist >= 0) {
        this.$message.warning('不能在同一场景相同位置添加节点')
        return false
      }
      const index = this.tourMarkers.length + 1
      const id = `${
        this.currentScene.id
      }_${new Date().getTime()}_${index}_tour`
      const options = {
        id: id,
        position: position,
        html: `<div class="tour-marker">${index}</div>`,
      }
      const item = {
        code: id,
        sceneId: this.currentScene.id,
        productId: this.product.id,
        sceneTitle: this.currentScene.title,
        index: index,
        lineClass: '',
        position: options.position,
        zoomLevel: this.vrViewer.getZoomLevel(),
        marker: options,
        waitTime: 5,
        content: '',
        voice: '',
      }
      this.tourMarkers.push(item)
      const kIndex = this.tourMarkers.length - 1
      if (kIndex - 1 >= 0) {
        const lineClass =
          this.tourMarkers[kIndex - 1]['sceneId'] !== item.sceneId
            ? 'tour-item-index-line-gradient'
            : ''
        this.tourMarkers[kIndex - 1]['lineClass'] = lineClass
        // console.log('item:', item, this.tourMarkers[kIndex - 1])
      }

      this.markersPlugin.addMarker(options)
      // setTimeout(() => {
      //   const marker = this.markersPlugin.getMarker(id)
      //   this.moveTourMarker(marker.element)
      // }, 100)
    },
    // 导游节点:开始记录/停止记录
    onTour(value) {
      this.tourSwitchValue = value
      if (!value) {
        // 停止记录后保存节点
        tourNodesSet(this.product.id, {
          nodes: this.tourMarkers,
        })
          .then(() => {
            this.$message.success(
              this.tourMarkers.length > 0 ? '节点保存成功' : '节点清空成功'
            )
          })
          .catch(() => {
            this.tourSwitchValue = false
            this.$refs.loopViewSetting.setTourSwitch(false)
          })
      }
    },
    // 跳转指定导游节点
    onGotoTourMarker(item) {
      this.execSceneChange(item.sceneId, 'tour', {
        tourMakerRenderCb: () => {
          this.markersPlugin.gotoMarker(item.code)
        },
      })
    },
    // 删除指定导游节点
    onDelTourMarker(item) {
      // console.log('onDelTourMarker item:', item)
      // this.onGotoTourMarker(item)
      setTimeout(() => {
        if ('id' in item) {
          this.$confirm('确认要删除节点吗?', '提示', {
            confirmButtonText: '确定',
            cancelButtonText: '取消',
            type: 'warning',
          })
            .then(() => {
              deleteTourNode(item.id).then(() => {
                this.handlerAfterDelTourMaker(item)
              })
            })
            .catch(() => {})
        } else {
          this.handlerAfterDelTourMaker(item)
        }
      }, 180)
    },
    // 删除导游节点后处理的逻辑
    handlerAfterDelTourMaker(item) {
      if (this.currentScene.id != item.sceneId) {
        // 删除的节点不属于当前场景,先切换场景后,在删除
        this.execSceneChange(item.sceneId, 'tour', {
          renderTourMarkers: false,
          renderCb: () => {
            // this.markersPlugin.removeMarker(item.code)
            this.tourMarkers.splice(item.index - 1, 1)
            this.reSortTourMarkers(item.index)
            setTimeout(() => {
              this.renderTourMarkers()
            }, 50)
          },
        })
      } else {
        // 当前场景删除节点
        this.markersPlugin.gotoMarker(item.code)
        this.markersPlugin.removeMarker(item.code)
        this.tourMarkers.splice(item.index - 1, 1)
        this.onClearTourMarkers(false)
        this.reSortTourMarkers(item.index)
        this.renderTourMarkers()
      }
    },
    // 导游节点重新排序
    reSortTourMarkers(beforeDelIndex) {
      for (let key in this.tourMarkers) {
        if (this.tourMarkers[key]['index'] > beforeDelIndex) {
          const diff = this.tourMarkers[key]['index'] - 1
          this.tourMarkers[key]['index'] = diff
          //218_1705592696338_1_tour
          this.tourMarkers[key]['code'] = `${
            this.tourMarkers[key]['sceneId']
          }_${new Date().getTime()}_${diff}_tour`
        }
      }
    },
    // 清空所有导游节点
    onClearTourMarkers(empty = true) {
      this.tourMarkers.some((item) => {
        if (this.currentScene.id === item.sceneId) {
          this.markersPlugin.removeMarker(item.code)
        }
      })
      if (empty) {
        this.tourMarkers = []
      }
    },
    // 设置指定导游节点
    onSaveTourMarker(node) {
      const index = this.tourMarkers.findIndex(
        (item) => item.code === node.code
      )
      if (index >= 0) {
        this.tourMarkers[index].waitTime = node.waitTime
        this.tourMarkers[index].content = node.content
        this.tourMarkers[index].voice = node.voice
      }
    },
    // 移动指定导游节点
    moveTourMarker(marker) {
      // 获取元素
      const container = this.vrViewer.container
      let isDragging = false
      let offsetX, offsetY
      let markerX = 0,
        markerY = 0
      // eslint-disable-next-line no-unused-vars
      let startLeft = 0,
        // eslint-disable-next-line no-unused-vars
        startTop = 0

      // 获取默认的 transform 属性
      const defaultTransform = window.getComputedStyle(marker).transform

      // 鼠标按下事件
      marker.addEventListener('mousedown', (e) => {
        isDragging = true

        // 阻止默认的拖动事件
        e.preventDefault()

        // 计算鼠标位置相对于 marker 的偏移量
        offsetX = e.clientX - marker.getBoundingClientRect().left
        offsetY = e.clientY - marker.getBoundingClientRect().top

        // 获取当前 marker 的位置
        markerX =
          marker.getBoundingClientRect().left -
          container.getBoundingClientRect().left
        markerY =
          marker.getBoundingClientRect().top -
          container.getBoundingClientRect().top

        // 获取起始位置
        startLeft = e.clientX - markerX
        startTop = e.clientY - markerY
      })

      // 鼠标移动事件
      document.addEventListener('mousemove', (e) => {
        if (isDragging) {
          // 计算 marker 新的位置
          const newX =
            e.clientX - container.getBoundingClientRect().left - offsetX
          const newY =
            e.clientY - container.getBoundingClientRect().top - offsetY

          // 计算移动距离
          const moveX = newX - markerX
          const moveY = newY - markerY

          // 获取默认 transform 中的 translate 值
          const defaultTranslate =
            defaultTransform === 'none'
              ? ''
              : defaultTransform.match(/matrix\(([^)]+)\)/)[1].split(', ')

          const translateX =
            defaultTranslate.length > 4 ? parseInt(defaultTranslate[4]) : 0
          const translateY =
            defaultTranslate.length > 5 ? parseInt(defaultTranslate[5]) : 0

          // 使用 translate 更新 marker 的位置
          marker.style.transform = `translate(${translateX + moveX}px, ${
            translateY + moveY
          }px)`
        }
      })

      // 鼠标释放事件
      document.addEventListener('mouseup', () => {
        isDragging = false
      })
    },
    // 获取已入库的导游节点
    async getTourNodes() {
      const nodes = await getTourNodes(this.product.id)
      this.tourMarkers = nodes.map((node) => {
        const options = {
          id: node.code,
          position: node.position,
          html: `<div class="tour-marker">${node.idx}</div>`,
        }
        return {
          id: node.id,
          code: node.code,
          sceneId: node.sceneId,
          productId: node.productId,
          sceneTitle: node.sceneTitle,
          index: node.idx,
          lineClass: '',
          position: node.position,
          zoomLevel: node.zoomLevel,
          marker: options,
          waitTime: node.waitTime,
          content: node.content,
          voice: node.voice,
        }
      })
    },
    // 获取已入库的电子地图场景点位
    async getPlaneGraph() {
      this.planeGraph = await getPlaneGraph(this.product.id)
      if (!this.planeGraph) {
        return
      }

      this.mapCenterPoint = this.planeGraph.center
      this.mapSceneNodes = this.planeGraph.markers.map((value) => {
        return {
          sceneId: value.sceneId,
          sceneTitle: value.sceneTitle,
          position: value.position,
          scale: value.scale,
        }
      })
    },
    // 添加电子地图底图
    onAddMapImage(url) {
      this.electronicMapBaseMapUrl = url
      setTimeout(() => {
        this.initMapBaseMapImage()
      }, 100)
    },
    onMapChangeType(newType, oldType) {
      if (newType === 'gis' && oldType === 'default') {
        this.electronicMapBaseMapUrl = ''
      }
    },
    onMarkerSceneMapNode(node) {
      // eslint-disable-next-line no-unused-vars
      console.log(
        'onMarkerSceneMapNode position:',
        node,
        this.addMapNodeSceneId
      )
      this.mapSceneNodes.push(node)
      this.activeMapSceneNode = node
      this.$refs.pointMarkerTool.disable()
    },
    // 添加电子地图场景标记点位
    onAddMapSceneMarker(value) {
      this.addMapNodeTrue = value.addMapSceneMarker
      this.addMapNodeSceneId = value.sceneId
      this.execSceneChange(value.sceneId, 'map')
      if (this.$refs.pointMarkerTool) {
        this.$refs.pointMarkerTool.sceneMarker(value)
      }
    },
    // 点击电子地图场景点位切换场景
    onMapChangeScene(sceneNode) {
      this.activeMapSceneNode = sceneNode
      this.execSceneChange(sceneNode.sceneId, 'map')
    },
    // 删除电子地图地图
    onRemoveMap() {
      this.activeMapSceneNode = null
      this.mapSceneNodes = []
      this.$refs.pointMarkerTool && this.$refs.pointMarkerTool.remove()
      this.$nextTick(() => {
        this.addMapNodeTrue = false
        this.electronicMapBaseMapUrl = ''
        this.selectCircleDgeCanvasWidth = undefined
        this.selectCircleDgeCanvasHeight = undefined
        this.mapCenterPoint = {
          position: { x: 0, y: 0 },
          scale: { scaleW: 1, scaleY: 1 },
        }
      })
    },
    // 删除电子地图场景点位
    onRemoveMapSceneMarker(node) {
      console.log('onRemoveMapSceneMarker node:', node)
      this.mapSceneNodes.splice(
        this.mapSceneNodes.findIndex((m) => m.sceneId === node.sceneId),
        1
      )
      this.$refs.pointMarkerTool.removeSceneMarker(node)
      if (this.mapSceneNodes.length > 0) {
        this.execSceneChange(
          this.mapSceneNodes[this.mapSceneNodes.length - 1]['sceneId'],
          'map'
        )
      }
    },
    // 保存电子地图场景点位
    onSaveMapSceneMarkers(formData) {
      saveMapSceneMarkers(this.product.id, Object.assign({
        mapCenterPoint: this.mapCenterPoint,
        markers: this.mapSceneNodes,
      }, formData))
        .then(() => {
          this.$message.success('保存成功')
          this.$refs.mapSetting.saveBtnLoad = false
          this.getPlaneGraph()
        })
        .catch(() => {
          this.$refs.mapSetting.saveBtnLoad = false
        })
    },

    onUpdateMapPointConfig(type, data) {
      //mapCenterPoint = data
      if (type === 'default') {
        this.mapCenterPoint = data
      } else if (type === 'gis') {
        console.log('gis', data)
        this.mapSceneNodes = data.sceneMarkers
        return saveMapSceneMarkers(this.product.id, {
          markers: data.sceneMarkers,
          type: 'gis'
        })
      }

    },
    //  设置全景图在电子地图上的位置
    onMarkerCenterMapPoint(type, tilesUrl = '') {
      //, this.selectCircleDgeCanvasWidth, this.selectCircleDgeCanvasHeight
      console.log('type:', type)
      this.$refs.mapPointConfig.open(
        type,
        'gis' === type ? tilesUrl : this.electronicMapBaseMapUrl,
        this.planeGraph ? this.planeGraph.center : null,
        this.mapSceneNodes
      )
    },
    // 初始化电子地图底图
    initMapBaseMapImage() {
      // 图片 URL
      this.initMapPlaneNode()
    },
    // 标记绑定拖动
    onMakerDragStart() {
      const that = this
      // 获取父元素
      const parentElement = document.querySelector('.psv-markers')
      parentElement.addEventListener('click', (event) => {
        if (this.polygonDraw.drawing) {
          console.log('client position:', event.clientX, event.clientY)
        }
        return true
      })
      parentElement.addEventListener('mousedown', (event) => {
        if (this.polygonDraw.drawing) {
          console.log('正在绘制多边形，无法进行操作1')
          return false
        }
        const marker = event.target.closest('.psv-marker')
        if (marker) {
          // 阻止事件冒泡，防止其他地方的 mousedown 事件被触发
          // console.log('event:', event)
          event.stopPropagation()

          // 阻止默认行为（如拖动）
          event.preventDefault()
        }
      })
      // 为父元素添加事件委托
      parentElement.addEventListener('pointerdown', (event) => {
        if (this.polygonDraw.drawing) {
          console.log('正在绘制多边形，无法进行操作2')
          return false
        }
        // 检查点击的目标是否是 psv-marker
        const marker = event.target.closest('.psv-marker')
        if (marker) {
          // 阻止事件冒泡，防止其他地方的 mousedown 事件被触发
          // console.log('event:', event)
          event.stopPropagation()

          // 调用鼠标按下处理函数
          onPointerDown(event, marker)
        }
      })

      function onPointerDown(event, marker) {
        // 捕获指针事件
        marker.setPointerCapture(event.pointerId)

        // 获取初始鼠标位置
        let startX = event.clientX
        let startY = event.clientY
        let isDragging = false

        // 获取初始 marker 位置
        let initialTranslate = getComputedStyle(marker).translate
        let [startTranslateX, startTranslateY] = initialTranslate
          .replace('translate(', '')
          .replace(')', '')
          .split(' ')
          .map((v) => parseFloat(v) || 0) // 确保解析出有效数字

        // 定义 pointermove 事件处理函数
        function onPointerMove(event) {
          // 计算鼠标移动的距离
          const dx = event.clientX - startX
          const dy = event.clientY - startY
          const area = Math.sqrt(dx * dx + dy * dy)
          // console.log('area:', area)
          if (area > 90) {
            isDragging = true
            // 计算新的位置
            const newX = startTranslateX + dx
            const newY = startTranslateY + dy
            if (newY === undefined) {
              return
            }
            const markerId = event.target.id.replace('psv-marker-', '')
            const hotpotIndex = that.hotpots.findIndex(
              (item) => item.uuid == markerId
            )
            if (hotpotIndex >= 0) {
              // const {width, height} = that.vrViewer.state.size
              const position =
                that.vrViewer.dataHelper.viewerCoordsToSphericalCoords({
                  x: newX,
                  y: newY,
                })
              console.log('Marker moved 3d to:', position)
              that.markersPlugin.updateMarker({
                id: markerId,
                position: position,
              })
              that.hotpots[hotpotIndex].iconMarkerParams.position = position
              that.$refs.hotpotSetting.updateHotpotPosition(
                hotpotIndex,
                position
              )
            }

            // 更新 marker 的 translate 样式
            marker.style.translate = `${newX}px ${newY}px`
            // 阻止默认行为（如文本选择）
            event.preventDefault()
            // 打印新位置坐标
            console.log(`Marker moved to: x=${newX}, y=${newY}`)
          }
        }

        // 定义 pointerup 事件处理函数
        function onPointerUp(event) {
          // 释放指针捕获
          if (isDragging) {
            marker.releasePointerCapture(event.pointerId)

            // 移除 pointermove 和 pointerup 事件监听器
            marker.removeEventListener('pointermove', onPointerMove)
            marker.removeEventListener('pointerup', onPointerUp)

            console.log('Drag ended.')
          } else {
            console.log('click')
            const markerId = event.target.id.replace('psv-marker-', '')
            if (markerId) {
              return that.vrOnClickMarker({ id: markerId })
            }
          }
        }

        // 添加事件监听器到 marker 元素
        marker.addEventListener('pointermove', onPointerMove)
        marker.addEventListener('pointerup', onPointerUp)
      }
    },
  },
}
</script>
